  dfm_weight(
    scheme = "prop"
  )

freq_weight &lt;- textstat_frequency(
  dfm_weight_pres,
  n = 15,
  groups = docvars(
    dfm_weight_pres,
    "President"
  )
)

freq_weight &lt;- freq_weight |&gt;
  group_by(group) |&gt;
  mutate(
    feature_order = reorder(
      feature,
      frequency
    )
  ) |&gt;
  ungroup()

ggplot(
  freq_weight,
  aes(
    x = frequency,
    y = feature_order
  )
) +
  geom_point() +
  facet_wrap(
    ~ group,
    scales = "free_y"
  ) +
  labs(
    title = "Most Frequent Terms by President After 2000",
    x = "Relative Frequency",
    y = NULL
  )

