Select Anchor Documents

available_years &lt;- docvars(
  dfmat_wf,
  "year"
)

if (
  2000 %in% available_years
) {
  anchor_early &lt;- which(
    available_years == 2000
  )[1]
} else {
  anchor_early &lt;- which.min(
    available_years
  )
}

if (
  2023 %in% available_years
) {
  anchor_late &lt;- which(
    available_years == 2023
  )[1]
} else {
  anchor_late &lt;- which.max(
    available_years
  )
}

if (
  length(anchor_early) == 0 ||
  length(anchor_late) == 0 ||
  anchor_early == anchor_late
) {
  stop(
    "Unable to identify two distinct Wordfish anchors."
  )
}

cat(
  "Anchor documents:",
  docnames(dfmat_wf)[anchor_early],
  "and",
  docnames(dfmat_wf)[anchor_late],
  "\n"
)

