Wordfish Feature Positions

highlight_terms &lt;- intersect(
  c(
    "taiwan",
    "pla",
    "nuclear",
    "missile",
    "cyber",
    "space",
    "carrier",
    "ai"
  ),
  featnames(dfmat_wf)
)

# textplot_scale1d() can sometimes fail during Quarto rendering
# when feature coordinates are non-finite. Only draw it when the
# required model values are valid.

feature_positions_safe &lt;- TRUE

if (
  "beta" %in% names(tmod_wf)
) {
  feature_positions_safe &lt;- all(
    is.finite(
      tmod_wf$beta
    )
  )
}

if (
  feature_positions_safe &&
  length(highlight_terms) &gt; 0
) {

  tryCatch(
    {
      textplot_scale1d(
        tmod_wf,
        margin = "features",
        highlighted = highlight_terms,
        highlighted_color = "firebrick"
      )
    },

    error = function(e) {
      cat(
        "Feature-position plot could not be rendered safely:",
        e$message,
        "\n"
      )
    }
  )

} else {
  cat(
    "Feature-position plot skipped because valid feature coordinates were unavailable."
  )
}

