Lexicoder Sentiment Dictionary

dfmat_sent &lt;- dfm_lookup(
  dfmat_DOD,
  dictionary = data_dictionary_LSD2015
)

sent_df &lt;- convert(
  dfmat_sent,
  to = "data.frame"
)

sent_match &lt;- match(
  sent_df$doc_id,
  docnames(corp_DOD)
)

sent_df &lt;- sent_df |&gt;
  mutate(
    year = as.numeric(
      docvars(
        corp_DOD,
        "year"
      )[
        sent_match
      ]
    ),

    president = docvars(
      corp_DOD,
      "president"
    )[
      sent_match
    ],

    total = as.numeric(
      ntoken(
        corp_DOD
      )[
        sent_match
      ]
    ),

    net = positive - negative,

    sent_rate = ifelse(
      total &gt; 0,
      net / total,
      NA_real_
    )
  ) |&gt;
  filter(
    is.finite(year),
    is.finite(sent_rate)
  ) |&gt;
  arrange(year)

ggplot(
  sent_df,
  aes(
    x = year,
    y = sent_rate
  )
) +
  geom_line(
    color = "gray60",
    linetype = "dashed"
  ) +
  geom_point(
    aes(
      color = president
    ),
    size = 3
  ) +
  geom_smooth(
    method = "loess",
    se = TRUE,
    color = "gray40",
    alpha = 0.15
  ) +
  geom_hline(
    yintercept = 0,
    linetype = "dotted"
  ) +
  scale_color_manual(
    values = pres_colors,
    na.value = "gray50"
  ) +
  labs(
    title = "Net Sentiment of DOD China Reports Over Time",
    subtitle = "LSD2015: (Positive − Negative) / Total Tokens",
    x = "Year",
    y = "Net Sentiment Rate",
    color = "President"
  ) +
  theme_bw(
    base_size = 16
  ) +
  theme(
    legend.position = "bottom"
  )

